using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "UltranovaTag", menuName = "Data/Battle/Battle Actions/Tags/UltranovaTag", order = 0)]
public class UltranovaTag : Tag
{
	[SerializeField]
	private BattleAction negativeAction;

	[SerializeField]
	private BattleAction finalAction;

	[SerializeField]
	private int finalActionValue;

	public override string GetTagDescription()
	{
		return string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(base.TagIDDescription), finalAction.GetActionName(), finalActionValue, negativeAction.GetActionName());
	}
}
